fn register_c_traits(lua: &Lua, g: &mlua::Table) -> Result<()> {
    let t: mlua::Table = match g.get::<Value>("C_Traits")? {
        Value::Table(t) => t,
        _ => lua.create_table()?,
    };
    register_c_traits_0(lua, &t)?;
    register_c_traits_1(lua, &t)?;
    g.set("C_Traits", t)?;
    Ok(())
}

